result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_noise.py", "content": "import math

from noise import fbm


def _pearson(xs, ys):
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    cov = sum((a - mx) * (b - my) for a, b in zip(xs, ys))
    vx = sum((a - mx) ** 2 for a in xs)
    vy = sum((b - my) ** 2 for b in ys)
    if vx == 0 or vy == 0:
        return 0.0
    return cov / math.sqrt(vx * vy)


def _samples(seed):
    return [fbm(i / 10.0, j / 10.0, octaves=4, seed=seed)
            for j in range(200) for i in range(200)]


def test_output_in_unit_interval():
    vals = _samples(seed=7)
    assert all(0.0 <= v <= 1.0 for v in vals)


def test_determinism_per_seed():
    a = _samples(seed=123)
    b = _samples(seed=123)
    c = _samples(seed=124)
    assert a == b
    assert a != c


def test_continuity():
    step = 0.01
    prev_row = None
    for j in range(200):
        row = [fbm(i * step, j * step, octaves=4, seed=5) for i in range(200)]
        for i in range(199):
            assert abs(row[i + 1] - row[i]) < 0.05
            if prev_row is not None:
                assert abs(row[i] - prev_row[i]) < 0.05
        prev_row = row


def test_seeds_decorrelated():
    a = _samples(seed=1)
    b = _samples(seed=999)
    assert abs(_pearson(a, b)) < 0.3
